            save_clicked = True
            break
        except Exception:
            continue

    # If no labeled Save button was found, try submitting by pressing Enter in a filled field.
    if not save_clicked:
        try:
            # Press Enter in City field as a fallback submit
            await page.get_by_label("City").press("Enter")
        except Exception:
            pass

    # Wait for network to settle after the final action
    await page.wait_for_load_state("networkidle")

