async def act(page):
    # We're starting from the Orders listing page. The target order number 000000065
    # has a view link that points to /index.php/admin/sales_order/view/order_id/438/.
    # Use a relative goto to open that order's view page, then edit the address fields
    # and save. We do not use any knowledge_base helper functions because none are
    # provided.

    # 1) Navigate directly to the order view page for the internal order id (438)
    await page.goto("/index.php/admin/sales_order/view/order_id/438/")
    await page.wait_for_load_state("networkidle")

    # 2) If the order view page has an Edit button to enable address editing, click it.
    try:
        await page.get_by_role("button", name="Edit").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        # If no Edit button is present, it may already be editable or address editing
        # is available via another control; continue regardless.
        pass

    # 3) Fill address fields. Magento admin labels vary; try multiple common labels.
    street_labels = ["Street Address", "Street 1", "Street", "Address", "Address 1"]
    for lbl in street_labels:
        try:
            await page.get_by_label(lbl).fill("789 Pine Lane")
            break
        except Exception:
            continue

    city_labels = ["City", "Town/City"]
    for lbl in city_labels:
        try:
            await page.get_by_label(lbl).fill("San Francisco")
            break
        except Exception:
            continue

    region_labels = ["State/Province", "Region", "State"]
    for rlbl in region_labels:
        try:
            elm = page.get_by_label(rlbl)
            # Try selecting by visible label first, then by common value
            try:
                await elm.select_option(label="California")
                break
            except Exception:
                try:
                    await elm.select_option(value="CA")
                    break
                except Exception:
                    continue
        except Exception:
            continue

    postal_labels = ["Zip/Postal Code", "ZIP/Postal Code", "ZIP Code", "Postal Code", "Postcode"]
    for plbl in postal_labels:
        try:
            await page.get_by_label(plbl).fill("94102")
            break
        except Exception:
            continue

    # 4) Ensure Country is United States if a country select exists
    try:
        await page.get_by_label("Country").select_option(label="United States")
    except Exception:
        try:
            await page.get_by_label("Country").select_option(value="US")
        except Exception:
            pass

    # 5) Click Save to persist changes. Try a few plausible Save button names.
    # Clicking Save may navigate away; make it the last interaction.
    save_clicked = False
    for btn_name in ["Save", "Save Order", "Submit", "Save Address"]:
        try:
            await page.get_by_role("button", name=btn_name).click()
            save_clicked = True
            break
        except Exception:
            continue

    # If no labeled Save button was found, try submitting by pressing Enter in a filled field.
    if not save_clicked:
        try:
            # Press Enter in City field as a fallback submit
            await page.get_by_label("City").press("Enter")
        except Exception:
            pass

    # Wait for network to settle after the final action
    await page.wait_for_load_state("networkidle")

